SELECT wp_wc_orders.id FROM wp_wc_orders  WHERE 1=1 AND (wp_wc_orders.status IN ('wc-pending','wc-processing','wc-on-hold','wc-completed','wc-refunded','wc-checkout-draft')) AND (wp_wc_orders.type IN ('shop_order','shop_order_refund')) AND EXISTS (SELECT 1 FROM wp_wc_orders_meta k WHERE k.order_id = wp_wc_orders.id AND k.meta_key IN ('_m1_marker','_m2_marker')) AND NOT EXISTS (SELECT 1 FROM wp_wc_orders_meta s WHERE s.order_id = wp_wc_orders.id AND ((s.meta_key = '_m1_status' AND s.meta_value IN ('M1_GO')) OR (s.meta_key = '_m2_status' AND s.meta_value IN ('M2_GO'))))  ORDER BY wp_wc_orders.date_created_gmt DESC LIMIT 0, 20

SELECT COUNT(*) FROM wp_wc_orders  WHERE 1=1 AND (wp_wc_orders.status IN ('wc-pending','wc-processing','wc-on-hold','wc-completed','wc-refunded','wc-checkout-draft')) AND (wp_wc_orders.type IN ('shop_order','shop_order_refund')) AND EXISTS (SELECT 1 FROM wp_wc_orders_meta k WHERE k.order_id = wp_wc_orders.id AND k.meta_key IN ('_m1_marker','_m2_marker')) AND NOT EXISTS (SELECT 1 FROM wp_wc_orders_meta s WHERE s.order_id = wp_wc_orders.id AND ((s.meta_key = '_m1_status' AND s.meta_value IN ('M1_GO')) OR (s.meta_key = '_m2_status' AND s.meta_value IN ('M2_GO'))))
